import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { copyFile, mkdir, readFile, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";

const [output, ...options] = process.argv.slice(2);
if (!output) {
  throw new Error("usage: node scripts/collect-stage2-evidence.mjs <output-directory> [--platform-evidence=<platform>:<log>]");
}
const root = process.cwd();
await mkdir(output, { recursive: true });
const importedEvidence = parsePlatformEvidence(options);

const currentPlatform = platformName(process.platform);
const invocation = process.platform === "win32"
  ? { executable: "pwsh", args: ["-NoProfile", "-File", "scripts/verify-stage2.ps1"] }
  : { executable: "bash", args: ["scripts/verify-stage2.sh"] };
const startedAt = new Date().toISOString();
const started = Date.now();
const result = spawnSync(invocation.executable, invocation.args, {
  cwd: root,
  encoding: "utf8",
  env: process.env,
  maxBuffer: 64 * 1024 * 1024,
});
const stdout = result.stdout ?? "";
const stderr = result.stderr ?? "";
await writeFile(path.join(output, "stage2-gate.stdout.log"), stdout);
await writeFile(path.join(output, "stage2-gate.stderr.log"), stderr);

const check = {
  schemaVersion: "1.0",
  checkId: "stage2-offline-and-native-smoke",
  platform: currentPlatform,
  startedAt,
  durationMs: Date.now() - started,
  exitCode: result.status ?? -1,
  status: result.status === 0 ? "passed" : "failed",
  stdoutSha256: sha256(stdout),
  stderrSha256: sha256(stderr),
};
const checks = [check];
for (const [platform, source] of importedEvidence) {
  if (platform === currentPlatform) throw new Error(`platform evidence duplicates current platform: ${platform}`);
  const contents = await readFile(source);
  verifyPlatformEvidence(platform, contents.toString("utf8"));
  const filename = `stage2-${platform}-smoke.log`;
  const destination = path.join(output, filename);
  if (path.resolve(source) !== path.resolve(destination)) await copyFile(source, destination);
  checks.push({
    schemaVersion: "1.0",
    checkId: "stage2-workspace-tools-native-smoke",
    platform,
    status: "passed",
    imported: true,
    evidence: filename,
    evidenceSha256: sha256(contents),
  });
}
await writeFile(path.join(output, "verification-log.ndjson"),
  `${checks.map((entry) => JSON.stringify(entry)).join("\n")}\n`);

const fixtureManifest = JSON.parse(await readFile(path.join(root, "contracts/fixtures/manifest.json"), "utf8"));
const protocolTrace = {
  schemaVersion: "1.0",
  traceType: "stage2-pi-golden-oracle",
  sourceRevision: fixtureManifest.sourceRevision,
  redaction: {
    rawProviderHeadersIncluded: false,
    credentialsIncluded: false,
    environmentIncluded: false,
  },
  fixtures: fixtureManifest.fixtures.map((fixture) => ({
    fixtureId: fixture.id,
    domain: fixture.domain,
    rawSha256: fixture.rawSha256,
    expectedSha256: fixture.expectedSha256,
  })),
};
await writeFile(path.join(output, "protocol-trace.redacted.json"), `${JSON.stringify(protocolTrace, null, 2)}\n`);

const requiredPlatforms = ["windows", "macos", "linux"];
const stage2ExitPlatforms = new Set(["windows", "linux"]);
const platforms = Object.fromEntries(requiredPlatforms.map((platform) => {
  const platformCheck = checks.find((entry) => entry.platform === platform && entry.status === "passed");
  return [platform, {
    status: platformCheck ? "passed" : "not_run",
    evidence: platformCheck?.evidence ?? (platform === currentPlatform ? "verification-log.ndjson" : null),
    requiredForStage2Exit: stage2ExitPlatforms.has(platform),
  }];
}));
const failures = [];
if (check.status !== "passed") {
  failures.push({
    code: "stage2.gate_failed",
    platform: currentPlatform,
    exitCode: check.exitCode,
    evidence: ["stage2-gate.stdout.log", "stage2-gate.stderr.log"],
    impact: "blocks_stage2_exit",
  });
}
for (const platform of requiredPlatforms) {
  if (platforms[platform].status !== "passed") failures.push({
    code: "stage2.platform_runner_unavailable",
    platform,
    status: "not_run",
    impact: stage2ExitPlatforms.has(platform) ? "blocks_stage2_exit" : "follow_up_platform_matrix",
  });
}
await writeFile(path.join(output, "failure-evidence.ndjson"),
  failures.length === 0 ? "" : `${failures.map((failure) => JSON.stringify(failure)).join("\n")}\n`);

let resolvedFailureCount = 0;
try {
  const resolved = await readFile(path.join(output, "resolved-failure-evidence.ndjson"), "utf8");
  const records = resolved.split(/\r?\n/).filter(Boolean).map((line) => JSON.parse(line));
  if (records.some((record) => record.status !== "resolved")) {
    throw new Error("resolved failure evidence contains a non-resolved record");
  }
  resolvedFailureCount = records.length;
} catch (error) {
  if (error?.code !== "ENOENT") throw error;
}

const artifacts = {};
const artifactNames = [
  "verification-log.ndjson",
  "protocol-trace.redacted.json",
  "failure-evidence.ndjson",
  "stage2-gate.stdout.log",
  "stage2-gate.stderr.log",
  ...(resolvedFailureCount > 0 ? ["resolved-failure-evidence.ndjson"] : []),
  ...checks.flatMap((entry) => entry.evidence && entry.evidence !== "verification-log.ndjson" ? [entry.evidence] : []),
];
for (const filename of new Set(artifactNames)) {
  artifacts[filename] = { sha256: sha256(await readFile(path.join(output, filename))) };
}
const complete = check.status === "passed"
  && [...stage2ExitPlatforms].every((platform) => platforms[platform].status === "passed");
const manifest = {
  schemaVersion: "1.0",
  stage: 2,
  status: complete ? "passed" : "incomplete",
  generatedAt: new Date().toISOString(),
  source: {
    repositoryHead: git(["rev-parse", "HEAD"]),
    workingTreeDirty: git(["status", "--porcelain"]).length > 0,
    piRevision: fixtureManifest.sourceRevision,
    fixtureDomains: fixtureManifest.fixtures.map((fixture) => fixture.domain),
  },
  environment: {
    platform: currentPlatform,
    osRelease: os.release(),
    architecture: os.arch(),
    java: version("java", ["-version"]),
    node: process.version,
  },
  constraints: {
    offlineGate: true,
    realProviderUsed: false,
    envFileRead: false,
    secretsLogged: false,
  },
  platforms,
  checks,
  resolvedFailureCount,
  artifacts,
};
await writeFile(path.join(output, "verification-manifest.json"), `${JSON.stringify(manifest, null, 2)}\n`);
process.stdout.write(`Stage 2 evidence status: ${manifest.status}; output: ${output}\n`);
if (check.status !== "passed") process.exitCode = 1;

function platformName(value) {
  if (value === "win32") return "windows";
  if (value === "darwin") return "macos";
  if (value === "linux") return "linux";
  throw new Error(`unsupported native platform: ${value}`);
}

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

function git(args) {
  const command = spawnSync("git", args, { cwd: root, encoding: "utf8" });
  if (command.status !== 0) throw new Error(command.stderr || "git command failed");
  return command.stdout.trim();
}

function version(executable, args) {
  const command = spawnSync(executable, args, { cwd: root, encoding: "utf8" });
  return `${command.stdout ?? ""}\n${command.stderr ?? ""}`.trim().split(/\r?\n/, 1)[0];
}

function parsePlatformEvidence(options) {
  const prefix = "--platform-evidence=";
  const result = new Map();
  for (const option of options) {
    if (!option.startsWith(prefix)) throw new Error(`unknown option: ${option}`);
    const value = option.slice(prefix.length);
    const separator = value.indexOf(":");
    if (separator < 1 || separator === value.length - 1) {
      throw new Error(`invalid platform evidence: ${option}`);
    }
    const platform = value.slice(0, separator);
    if (!new Set(["windows", "macos", "linux"]).has(platform)) {
      throw new Error(`unsupported evidence platform: ${platform}`);
    }
    if (result.has(platform)) throw new Error(`duplicate platform evidence: ${platform}`);
    result.set(platform, value.slice(separator + 1));
  }
  return result;
}

function verifyPlatformEvidence(platform, contents) {
  const requiredMarkers = [
    "BUILD SUCCESSFUL",
    ":ji-workspace-local:test",
    "public Java module boundaries verified",
    "public naming conventions verified",
  ];
  if (contents.includes("BUILD FAILED")) throw new Error(`${platform} evidence records a failed build`);
  for (const marker of requiredMarkers) {
    if (!contents.includes(marker)) throw new Error(`${platform} evidence is missing marker: ${marker}`);
  }
}
